import { html } from "../../../../html.js";
import { useMemo, useState } from "/prototype/vendor/preact-hooks.js";
import { Dialog, Icon, StatusPill, Tabs } from "../../ui/index.js";
import PageVariants from "../../ui/PageVariants.js";
import { activity, fleetAgents, fleetDevices, fleetOrgs } from "./data.js";

const notify=(setToast,message)=>{setToast(message);setTimeout(()=>setToast(''),2200)};
const Meter=({value})=>html`<span class=${`p-fleet-meter p-fleet-meter-${value}`}><i></i></span>`;
function Action({children,onClick,primary=false}){return html`<button class=${`p-fleet-action ${primary?'p-fleet-primary':''}`} onClick=${onClick}>${children}</button>`}
function DeviceIcon({status}){return html`<span class=${`p-fleet-device-icon ${status==='online'?'p-fleet-online':'p-fleet-offline'}`}><${Icon} name="server"/></span>`}
function Toast({toast}){return toast&&html`<div class="p-fleet-toast" role="status"><${Icon} name="check"/>${toast}</div>`}
function Enroll({close,setToast}){const [code,setCode]=useState('DUR-7K4P');return html`<${Dialog} onClose=${close}><div class="p-fleet-dialog"><header><div><b>Enroll a device</b><small>Pair a daemon with this workspace.</small></div><button onClick=${close} aria-label="Close">×</button></header><ol><li>Install <code>durable daemon</code> on the device.</li><li>Run <code>durable pair ${code}</code></li><li>Approve the device fingerprint below.</li></ol><label>Pairing code<input value=${code} onInput=${e=>setCode(e.target.value)}/></label><footer><${Action} onClick=${()=>{close();notify(setToast,'Pairing request created')}} primary=${true}>Create pairing request</${Action}></footer></div></${Dialog}>`}
function AgentDrawer({agent,close,setToast}){const [tab,setTab]=useState('Overview');return html`<aside class="p-fleet-drawer"><header><button onClick=${close} aria-label="Close agent detail">←</button><div><b>${agent.id}</b><small>${agent.device} · v${agent.version}</small></div><${StatusPill} status=${agent.paused?'held':'running'}/></header><${Tabs} value=${tab} setValue=${setTab} items=${['Overview','Logs','Access']}/>${tab==='Overview'?html`<div class="p-fleet-drawer-body"><label>DAEMON</label><p><span class="p-fleet-health"></span>${agent.daemon}</p><label>DAILY BUDGET</label><${Meter} value=${agent.budget}/><p>${agent.budget}% allocated · $${(agent.budget/10).toFixed(2)} spent</p><label>RUN CAPACITY</label><p>${agent.work}</p><div class="p-fleet-drawer-actions"><${Action} onClick=${()=>notify(setToast,agent.paused?'Agent resumed':'Agent paused')}>${agent.paused?'Resume agent':'Pause agent'}</${Action}><${Action} onClick=${()=>notify(setToast,'Budget editor opened')}>Set budget</${Action}></div></div>`:tab==='Logs'?html`<pre class="p-fleet-logs">10:42:18 heartbeat accepted
10:42:14 queue checkpoint saved
10:41:58 policy evaluation complete
10:41:55 daemon ready</pre>`:html`<div class="p-fleet-drawer-body"><label>CAPABILITIES</label>${fleetDevices.find(d=>d.id===agent.device)?.capabilities.map(c=>html`<span class="p-fleet-cap">${c}</span>`)}<label>APPROVAL BOUNDARY</label><p>Passkey required for protected changes.</p></div>`}</aside>`}
function CommandCenter(){const [filter,setFilter]=useState('All devices'),[selected,setSelected]=useState(null),[enroll,setEnroll]=useState(false),[toast,setToast]=useState('');const visible=useMemo(()=>fleetDevices.filter(d=>filter==='All devices'||(filter==='Needs attention'?d.alerts:d.status==='online')),[filter]);return html`<section class="p-fleet-layout p-fleet-command"><header class="p-fleet-page-head"><div><p>FLEET CONTROL</p><h1>Agents at work, without losing the thread.</h1><span>4 devices · 3 healthy daemons · 2 policy signals</span></div><div class="p-fleet-head-actions"><${Action} onClick=${()=>setEnroll(true)} primary=${true}><${Icon} name="plus"/> Enroll device</${Action}><${Action} onClick=${()=>notify(setToast,'Update staged for 3 eligible devices')}>Stage update</${Action}></div></header><div class="p-fleet-overview"><article><small>ONLINE</small><b>3 <em>/ 4 devices</em></b><span class="p-fleet-up">↑ stable since 09:20</span></article><article><small>ACTIVE RUNS</small><b>4 <em>across 3 agents</em></b><span>2 waiting for approval</span></article><article><small>DAILY SPEND</small><b>$26.70 <em>/ $60</em></b><${Meter} value=${44}/></article><article class="p-fleet-alert-card"><small>ATTENTION</small><b>3 <em>signals</em></b><button onClick=${()=>setFilter('Needs attention')}>Review health →</button></article></div><div class="p-fleet-toolbar"><${Tabs} value=${filter} setValue=${setFilter} items=${['All devices','Online','Needs attention']}/><span>Last heartbeat: now</span></div><div class="p-fleet-device-list">${visible.map(device=>html`<button class="p-fleet-device-row" onClick=${()=>setSelected(fleetAgents.find(a=>a.device===device.id))}><${DeviceIcon} status=${device.status}/><span class="p-fleet-device-name"><b>${device.id}</b><small>${device.region} · v${device.version}</small></span><span class="p-fleet-resource"><small>CPU ${device.cpu}%</small><${Meter} value=${device.cpu}/></span><span class="p-fleet-resource"><small>MEM ${device.memory}%</small><${Meter} value=${device.memory}/></span><span class="p-fleet-heart"><i class=${device.status==='online'?'p-fleet-pulse':''}></i>${device.heartbeat}</span>${device.alerts>0?html`<strong class="p-fleet-alert-count">${device.alerts}</strong>`:html`<span></span>`}<${Icon} name="chevron-right"/></button>`)}</div>${selected&&html`<${AgentDrawer} agent=${selected} close=${()=>setSelected(null)} setToast=${setToast}/>`}${enroll&&html`<${Enroll} close=${()=>setEnroll(false)} setToast=${setToast}/>`}<${Toast} toast=${toast}/></section>`}
function Topology(){const [selected,setSelected]=useState(fleetAgents[0]),[toast,setToast]=useState('');return html`<section class="p-fleet-layout p-fleet-topology"><header class="p-fleet-page-head"><div><p>LIVE TOPOLOGY</p><h1>Trust paths are visible before work starts.</h1><span>Heartbeat graph · refreshed 10 seconds ago</span></div><${Action} onClick=${()=>notify(setToast,'Health probe requested')}><${Icon} name="activity"/> Run health probe</${Action}></header><div class="p-fleet-topology-grid"><div class="p-fleet-map"><div class="p-fleet-map-title"><b>Workspace control plane</b><span><i></i> 3 connected</span></div><div class="p-fleet-core"><span>Durable</span><small>control plane</small></div><div class="p-fleet-orbit p-fleet-orbit-a"></div><div class="p-fleet-orbit p-fleet-orbit-b"></div>${fleetAgents.map((agent,index)=>html`<button class=${`p-fleet-node p-fleet-node-${index} ${selected.id===agent.id?'p-fleet-node-active':''}`} onClick=${()=>setSelected(agent)}><i class=${agent.daemon==='offline'?'p-fleet-down':''}></i><${Icon} name="bot"/><b>${agent.id}</b><small>${agent.device}</small></button>`)}</div><aside class="p-fleet-inspector"><header><span>SELECTED AGENT</span><${StatusPill} status=${selected.daemon==='offline'?'error':'running'}/></header><h2>${selected.id}</h2><p>${selected.work}</p><div class="p-fleet-signal"><label>Heartbeat history</label><svg viewBox="0 0 210 44" role="img" aria-label="Heartbeat history"><polyline points="0,28 18,25 34,29 52,14 70,25 88,18 106,24 124,8 142,16 160,14 178,22 210,10" fill="none" stroke="var(--accent)" stroke-width="2"/></svg></div><dl><div><dt>Version</dt><dd>${selected.version}</dd></div><div><dt>Budget</dt><dd>${selected.budget}%</dd></div><div><dt>Daemon</dt><dd>${selected.daemon}</dd></div></dl><${Action} onClick=${()=>notify(setToast,'Opened agent log tail')}>Tail logs</${Action}></aside></div><div class="p-fleet-event-strip"><b>Health alerts</b>${activity.map(([device,title,detail])=>html`<button onClick=${()=>setSelected(fleetAgents.find(a=>a.device===device)||fleetAgents[0])}><span class="p-fleet-event-device">${device}</span><strong>${title}</strong><small>${detail}</small></button>`)}</div><${Toast} toast=${toast}/></section>`}
function Governance(){const [org,setOrg]=useState('All organizations'),[toast,setToast]=useState('');const agents=org==='All organizations'?fleetAgents:fleetAgents.filter(agent=>agent.org===org);return html`<section class="p-fleet-layout p-fleet-governance"><header class="p-fleet-page-head"><div><p>FLEET GOVERNANCE</p><h1>Permissions, budgets, and change posture.</h1><span>Make safe autonomy legible to operators.</span></div><${Action} onClick=${()=>notify(setToast,'Policy export prepared')}>Export policy</${Action}></header><div class="p-fleet-governance-main"><aside class="p-fleet-orgs"><b>ORGANIZATIONS</b><button class=${org==='All organizations'?'p-fleet-org-active':''} onClick=${()=>setOrg('All organizations')}>All organizations <span>4</span></button>${fleetOrgs.map(item=>html`<button class=${org===item.name?'p-fleet-org-active':''} onClick=${()=>setOrg(item.name)}>${item.name}<span>${item.agents}</span></button>`)}<div class="p-fleet-policy-note"><${Icon} name="shield-check"/><b>Protected changes</b><small>Passkey approval remains required.</small></div></aside><div class="p-fleet-matrix"><div class="p-fleet-matrix-head"><div><b>Agent capability matrix</b><small>Scope and operating envelope by agent</small></div><button onClick=${()=>notify(setToast,'Capability review started')}>Review changes</button></div><div class="p-fleet-table-wrap"><table><thead><tr><th>Agent</th><th>Daemon</th><th>GitHub</th><th>Shell</th><th>Browser</th><th>Daily budget</th><th>Action</th></tr></thead><tbody>${agents.map(agent=>{const caps=fleetDevices.find(d=>d.id===agent.device)?.capabilities||[];return html`<tr><td><b>${agent.id}</b><small>${agent.device}</small></td><td><${StatusPill} status=${agent.daemon==='offline'?'error':'running'}/></td>${['GitHub','Shell','Browser'].map(cap=>html`<td><span class=${caps.includes(cap)?'p-fleet-granted':'p-fleet-denied'}>${caps.includes(cap)?'Granted':'—'}</span></td>`)}<td><${Meter} value=${agent.budget}/><small>${agent.budget}%</small></td><td><button onClick=${()=>notify(setToast,`Policy editor opened for ${agent.id}`)}>Manage</button></td></tr>`})}</tbody></table></div></div></div><div class="p-fleet-budget-panel"><header><b>Organization budget posture</b><span>Today</span></header>${fleetOrgs.map(item=>html`<article><div><b>${item.name}</b><span>$${item.spend} / $${item.limit}</span></div><${Meter} value=${Math.round(item.spend/item.limit*100)}/><small>${item.agents} agents · Protected changes</small></article>`)}</div><${Toast} toast=${toast}/></section>`}
export default function FleetPage(){return html`<main class="e-page p-fleet-page"><${PageVariants} variants=${[{key:'1',name:'Command center',render:()=>html`<${CommandCenter}/>`},{key:'2',name:'Topology',render:()=>html`<${Topology}/>`},{key:'3',name:'Governance',render:()=>html`<${Governance}/>`}]}/></main>`}
